-- Chat rows are written only by the backend (postgres role, which bypasses RLS).
CREATE TABLE IF NOT EXISTS "public"."chat_threads" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    bigint                   NOT NULL,
  "title"      text                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chat_threads_pkey" PRIMARY KEY (id),
  CONSTRAINT "chat_threads_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "chat_threads_user_id_updated_at_idx"
  ON "public"."chat_threads" (user_id, updated_at DESC);

ALTER TABLE "public"."chat_threads" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Ver mis propios chats" ON "public"."chat_threads"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));

CREATE TABLE IF NOT EXISTS "public"."chat_messages" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "thread_id"  bigint                   NOT NULL,
  "role"       text                     NOT NULL,
  "content"    text                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chat_messages_pkey" PRIMARY KEY (id),
  CONSTRAINT "chat_messages_thread_id_fkey" FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE,
  CONSTRAINT "chat_messages_role_check" CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text])))
);

CREATE INDEX IF NOT EXISTS "chat_messages_thread_id_id_idx"
  ON "public"."chat_messages" (thread_id, id);

ALTER TABLE "public"."chat_messages" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Ver mis propios mensajes" ON "public"."chat_messages"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS (
    SELECT 1
    FROM public.chat_threads
    WHERE chat_threads.id = chat_messages.thread_id
      AND chat_threads.user_id = public.get_current_user_id()
  )));
